css:
body :where([data-bz-node="ar"]) .bz-block{padding:0}
body :where([data-bz-node="ar"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="ar"]>.bz-container{padding-inline:0}

body [data-bz-node="ar"]{background:#fff;padding:90px 0 60px}
body [data-bz-node="ar"]>.bz-container{max-width:var(--container)}
body [data-bz-node="ar-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="ar-intro"] .bz-text,body [data-bz-node^="ar-stext-"] .bz-text{max-width:none;margin-top:22px}
body [data-bz-node="ar-intro"] p,body [data-bz-node^="ar-stext-"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="ar-intro"] p:last-child,body [data-bz-node^="ar-stext-"] p:last-child{margin:0}
body [data-bz-node="ar-intro"] a,body [data-bz-node^="ar-stext-"] a{color:var(--accent);text-decoration:none}
body [data-bz-node="ar-intro"] a:hover,body [data-bz-node^="ar-stext-"] a:hover{text-decoration:underline}
body [data-bz-node="ar-photos"]{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:36px}
body [data-bz-node="ar-photos"]>.bz-col{grid-column:auto}
body [data-bz-node^="ar-photo-"] figure{margin:0}
body [data-bz-node^="ar-photo-"] img{width:100%;aspect-ratio:1413/771;object-fit:cover;border-radius:0}
body [data-bz-node="ar-sections"]{display:block;margin-top:56px}
body [data-bz-node^="ar-sec-"]{display:block;margin-bottom:46px}
body [data-bz-node^="ar-sh-"] h3{font:700 28px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
@media (max-width:1100px){body [data-bz-node="ar"]{padding:64px 24px 40px}body [data-bz-node="ar-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="ar"]{padding:48px 20px 32px}body [data-bz-node="ar-h"] h2{font-size:26px}body [data-bz-node="ar-photos"]{grid-template-columns:1fr;gap:16px}body [data-bz-node^="ar-sh-"] h3{font-size:22px}body [data-bz-node="ar-sections"]{margin-top:40px}}
